                    break
                i += 1
            tokens.append(Token("number", text[start:i]))
            continue
        if re.match(r"[A-Za-z_?][A-Za-z0-9_?!-]*", text[i:]):
            m = re.match(r"[A-Za-z_?][A-Za-z0-9_?!-]*", text[i:])
