def open_file(path_text: str, raw: bool = False) -> Any:
    path = Path(path_text)
    text = path.read_text(encoding="utf-8")
    if raw:
        return text
    if path.suffix.lower() == ".json":
        return json.loads(text)
    if path.suffix.lower() == ".csv":
        return from_csv(text)
    return text


